package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import it.unimi.dsi.fastutil.objects.ObjectArrayList; import it.unimi.dsi.fastutil.objects.ObjectList; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.v898.serializer.TextSerializer_v898; import org.cloudburstmc.protocol.bedrock.packet.TextPacket; import org.cloudburstmc.protocol.common.util.TextConverter; import org.slf4j.Logger; import org.slf4j.LoggerFactory;
public class TextSerializer_v924 extends TextSerializer_v898 {public static final TextSerializer_v924 INSTANCE=new TextSerializer_v924();private static final Logger log=LoggerFactory.getLogger(TextSerializer_v924.class);
@Override public void serialize(ByteBuf b,BedrockCodecHelper h,TextPacket p){TextPacket.Type t=p.getType();TextConverter c=h.getTextConverter();CharSequence m=p.getMessage(CharSequence.class);Boolean nt=c.needsTranslation(m);b.writeBoolean(nt!=null?nt:p.isNeedsTranslation());String s;switch(t){case RAW:case TIP:case SYSTEM:b.writeByte(0);b.writeByte(t.ordinal());s=c.serialize(m);if(s.isEmpty()){s=" ";if(log.isDebugEnabled())log.debug("TextPacket of "+t+" with empty message");}h.writeString(b,s);break;case JSON:case WHISPER_JSON:case ANNOUNCEMENT_JSON:b.writeByte(0);b.writeByte(t.ordinal());s=c.serializeJson(m);if(s.isEmpty())s=" ";h.writeString(b,s);break;case CHAT:case WHISPER:case ANNOUNCEMENT:b.writeByte(1);b.writeByte(t.ordinal());h.writeString(b,p.getSourceName());s=c.serialize(m);if(s.isEmpty())s=" ";h.writeString(b,s);break;case TRANSLATION:case POPUP:case JUKEBOX_POPUP:b.writeByte(2);b.writeByte(t.ordinal());s=c.serializeWithArguments(m,p.getParameters());if(s.isEmpty())s=" ";h.writeString(b,s);h.writeArray(b,p.getParameters(),h::writeString);break;default:throw new UnsupportedOperationException("Unsupported TextType "+t);}h.writeString(b,p.getXuid());h.writeString(b,p.getPlatformChatId());String f=c.serialize(p.getFilteredMessage(CharSequence.class));h.writeOptional(b,x->!x.isEmpty(),f,(buf,hh,x)->hh.writeString(buf,x));}
@Override public void deserialize(ByteBuf b,BedrockCodecHelper h,TextPacket p){TextConverter c=h.getTextConverter();boolean nt=b.readBoolean();p.setNeedsTranslation(nt);switch(b.readByte()){case 0:TextPacket.Type t=TextPacket.Type.values()[b.readUnsignedByte()];p.setType(t);String s=h.readString(b);p.setMessage((t==TextPacket.Type.JSON||t==TextPacket.Type.WHISPER_JSON||t==TextPacket.Type.ANNOUNCEMENT_JSON)?c.deserializeJson(s,nt):c.deserialize(s,nt));break;case 1:p.setType(TextPacket.Type.values()[b.readUnsignedByte()]);p.setSourceName(h.readString(b));p.setMessage(c.deserialize(h.readString(b),nt));break;case 2:p.setType(TextPacket.Type.values()[b.readUnsignedByte()]);String s2=h.readString(b);ObjectList<String>ps=new ObjectArrayList<>();h.readArray(b,ps,h::readString);p.setMessage(c.deserializeWithArguments(s2,ps,nt));p.setParameters(ps);break;default:throw new UnsupportedOperationException("Not oneOf<MessageOnly, AuthorAndMessage, MessageAndParams>");}p.setXuid(h.readString(b));p.setPlatformChatId(h.readString(b));String f=h.readOptional(b,"",(buf,hh)->hh.readString(buf));p.setFilteredMessage(c.deserialize(f,nt));}}
